// HasCronTask applies the HasEdge predicate on the "cron_task" edge.
func HasCronTask() predicate.InputTask {
	return predicate.InputTask(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CronTaskTable, CronTaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCronTaskWith applies the HasEdge predicate on the "cron_task" edge with a given conditions (other predicates).
func HasCronTaskWith(preds ...predicate.CronTask) predicate.InputTask {
	return predicate.InputTask(func(s *sql.Selector) {
		step := newCronTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.InputTask) predicate.InputTask {
	return predicate.InputTask(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.InputTask) predicate.InputTask {
	return predicate.InputTask(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.InputTask) predicate.InputTask {
	return predicate.InputTask(sql.NotPredicates(p))
}
